<script setup lang="ts">
import {LayoutDashboard,FolderOpen,FileText,Bell,CalendarDays,ArrowRight,RefreshCw,Route,CheckCircle2} from 'lucide-vue-next'
definePageMeta({title:'Không gian hành chính cá nhân'})
type View={cases:{id:string;procedure_id:string;procedure_title:string;status:string;due_at:string|null;updated_at:string}[];
 plans:{id:string;title:string;event_code:string;status:string;steps:number}[];vaultCount:number;
 unreadAlerts:{id:string;title:string;created_at:string}[];tasks:{id:string;title:string;due_on:string}[];
 bookings:{id:string;starts_at:string;title:string}[];nextActions:{caseId:string;title:string;reason:string;url:string;kind:string}[];notice:string}
const {data:auth}=await useFetch<{authenticated:boolean}>('/api/auth/me',{key:'citizen-workspace-auth'})
const {data,error,refresh,pending}=await useFetch<View>('/api/citizen/workspace',{key:'citizen-workspace-v1',immediate:Boolean(auth.value?.authenticated)})
const {data:lifeSuggestions}=await useFetch<{items:{procedureId:string;title:string;source:string;reason:string}[];notice:string}>('/api/citizen/life-suggestions',{key:'citizen-journey-life-suggestions',immediate:Boolean(auth.value?.authenticated)})
const active=computed(()=>data.value?.cases.filter(c=>['submitted','processing','supplement'].includes(c.status)).length||0)
const drafts=computed(()=>data.value?.cases.filter(c=>c.status==='draft')||[])
const completed=computed(()=>data.value?.cases.filter(c=>c.status==='completed').length||0)
</script>
<template><div class="space-y-4"><section class="panel flex flex-wrap items-center justify-between gap-3 p-5"><div class="flex items-center gap-3"><LayoutDashboard class="text-brand-700" :size="27"/><div><h2 class="text-xl font-black">Không gian hành chính của tôi</h2><p class="text-sm text-muted">Tổng hợp hồ sơ, việc cần làm, giấy tờ, lộ trình và thông báo của tài khoản.</p></div></div><button v-if="auth?.authenticated" class="btn-outline !text-xs" :disabled="pending" @click="refresh()"><RefreshCw :size="15"/>Làm mới</button></section>
 <section v-if="!auth?.authenticated" class="panel p-5 text-sm"><NuxtLink to="/dang-nhap" class="font-bold text-brand-700 underline">Đăng nhập</NuxtLink> để xem dữ liệu của bạn.</section>
 <section v-else-if="error" class="panel p-5 text-rose-700">Không lấy được dữ liệu. <button class="underline" @click="refresh()">Thử lại</button></section>
 <template v-else-if="data"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div v-for="tile in [{label:'Hồ sơ đang xử lý',n:active,icon:FolderOpen},{label:'Bản nháp',n:drafts.length,icon:FileText},{label:'Đã hoàn thành',n:completed,icon:CheckCircle2},{label:'Giấy tờ trong kho',n:data.vaultCount,icon:FolderOpen}]" :key="tile.label" class="panel flex items-center gap-3 p-4"><component :is="tile.icon" :size="22" class="text-brand-700"/><div><p class="text-2xl font-black text-brand-900">{{tile.n}}</p><p class="text-xs text-muted">{{tile.label}}</p></div></div></div>
 <div class="grid gap-3 lg:grid-cols-2"><section class="panel space-y-3 p-4"><div class="flex items-center justify-between"><h3 class="flex items-center gap-2 font-extrabold"><Route :size="18"/>Lộ trình hành chính</h3><NuxtLink to="/lo-trinh-hanh-chinh" class="text-xs font-bold text-brand-700">Tạo mới →</NuxtLink></div><p v-if="!data.plans.length" class="text-sm text-muted">Chưa có lộ trình. Bạn có thể mô tả một sự kiện đời sống để nhận gợi ý.</p><NuxtLink v-for="plan in data.plans" :key="plan.id" :to="`/lo-trinh-hanh-chinh/${plan.id}`" class="flex items-center justify-between gap-2 rounded-lg border p-3 text-sm hover:bg-blue-50"><span><b>{{plan.title}}</b><small class="block text-muted">{{plan.steps}} thủ tục · {{plan.status}}</small></span><ArrowRight :size="16"/></NuxtLink></section>
 <section class="panel space-y-3 p-4"><div class="flex items-center justify-between"><h3 class="font-extrabold">Bản nháp — tiếp tục trên thiết bị khác</h3><NuxtLink to="/ho-so" class="text-xs font-bold text-brand-700">Tất cả →</NuxtLink></div><p v-if="!drafts.length" class="text-sm text-muted">Không có bản nháp.</p><NuxtLink v-for="item in drafts" :key="item.id" :to="`/nop-ho-so/${item.procedure_id}?draft=${item.id}&step=1`" class="flex items-center justify-between gap-2 rounded-lg border p-3 text-sm hover:bg-blue-50"><span><b>{{item.procedure_title}}</b><small class="block text-muted">{{item.id}}</small></span><ArrowRight :size="16"/></NuxtLink></section>
 <section class="panel space-y-3 p-4"><div class="flex items-center justify-between"><h3 class="flex items-center gap-2 font-extrabold"><Bell :size="18"/>Hành động cần thực hiện</h3><NuxtLink to="/thong-bao" class="text-xs font-bold text-brand-700">Thông báo →</NuxtLink></div><p v-if="!data.nextActions.length" class="text-sm text-muted">Chưa có hành động từ trạng thái hồ sơ hiện tại.</p><NuxtLink v-for="a in data.nextActions" :key="a.caseId" :to="a.url" class="block rounded-lg border p-3 hover:bg-blue-50"><b class="text-sm">{{a.title}}</b><p class="mt-1 text-xs text-muted">{{a.reason}}</p></NuxtLink><p class="text-xs text-muted">{{data.unreadAlerts.length}} thông báo chưa đọc được hiển thị gần nhất.</p></section>
 <section class="panel space-y-3 p-4"><div class="flex items-center justify-between"><h3 class="flex items-center gap-2 font-extrabold"><CalendarDays :size="18"/>Lịch và nghĩa vụ</h3><NuxtLink to="/lich-hanh-chinh" class="text-xs font-bold text-brand-700">Xem lịch →</NuxtLink></div><p v-if="!data.tasks.length&&!data.bookings.length" class="text-sm text-muted">Chưa có nhắc việc hoặc lịch hẹn.</p><div v-for="t in data.tasks.slice(0,5)" :key="t.id" class="rounded-lg border p-3 text-sm"><b>{{t.title}}</b><small class="block text-muted">Hạn: {{String(t.due_on).slice(0,10)}}</small></div><div v-for="b in data.bookings.slice(0,3)" :key="b.id" class="rounded-lg border p-3 text-sm"><b>{{b.title}}</b><small class="block text-muted">Lịch tại quầy: {{new Date(b.starts_at).toLocaleString('vi-VN')}}</small></div></section></div>
 <section v-if="lifeSuggestions?.items.length" class="panel space-y-3 p-4"><h3 class="font-extrabold">Thủ tục có thể liên quan đến lộ trình đã lưu</h3><p class="text-xs text-muted">Đề xuất từ sự kiện bạn đã chủ động nhập, chưa phải xác định nghĩa vụ hành chính.</p><NuxtLink v-for="item in lifeSuggestions.items" :key="item.procedureId" :to="item.source" class="block rounded-lg border p-3 hover:bg-blue-50"><b class="text-sm text-brand-900">{{item.title}}</b><small class="mt-1 block text-muted">{{item.reason}}</small></NuxtLink></section>
 <p class="text-xs text-muted">{{data.notice}}</p></template>
 </div></template>
